using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;

static class NamTests {
 public static int Run(string source,string folder){Directory.CreateDirectory(folder);var results=new List<object>();var json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};int failed=0;
  Action<string,Action> test=(name,action)=>{try{action();results.Add(new{name=name,status="PASS"});}catch(Exception e){failed++;results.Add(new{name=name,status="FAIL",error=e.Message});}};
  Action<bool> require=ok=>{if(!ok)throw new Exception("Assertion failed");};
  NamCapture capture=null;test("accept_slimmable_select_lite",()=>{capture=NamCapture.Read(source);require(capture.Wave.Length==8236);});
  test("byte_exact_vs_upstream_python",()=>{var expected=File.ReadAllBytes(Path.Combine(folder,"expected.wav"));require(capture.Wave.SequenceEqual(expected));});
  test("carrier_readback_exact",()=>NamCapture.VerifyCarrier(capture.Wave,capture.Wave));
  test("minus12_changes_only_output_head_scale",()=>{var adjusted=NamCapture.Read(source,-12);var before=NamCapture.AudioPayload(capture.Wave);var after=NamCapture.AudioPayload(adjusted.Wave);int offset=(8+3+49)*4;double ratio=BitConverter.ToSingle(after,offset)/BitConverter.ToSingle(before,offset);require(adjusted.Hash==capture.Hash&&adjusted.OutputDb==-12&&Math.Abs(ratio-Math.Pow(10,-12.0/20))<1e-7&&before.Take(offset).SequenceEqual(after.Take(offset))&&before.Skip(offset+4).SequenceEqual(after.Skip(offset+4)));});
  test("reject_mutated_carrier",()=>{var b=(byte[])capture.Wave.Clone();b[200]^=1;bool rejected=false;try{NamCapture.VerifyCarrier(capture.Wave,b);}catch(InvalidDataException){rejected=true;}require(rejected);});
  test("reject_integer_pcm_export",()=>{var b=(byte[])capture.Wave.Clone();b[20]=1;bool rejected=false;try{NamCapture.AudioPayload(b);}catch(InvalidDataException){rejected=true;}require(rejected);});
  test("builtin_model_zero_does_not_consume_user_ir",()=>require(NamGuards.FreeSlot(new string[128])==0));
  test("preserve_used_ir_slots",()=>{var slots=Enumerable.Repeat("Cab",128).ToArray();slots[37]="";require(NamGuards.FreeSlot(slots)==37);});
  test("refuse_full_bank",()=>{bool rejected=false;try{NamGuards.FreeSlot(Enumerable.Repeat("Cab",128).ToArray());}catch(IOException){rejected=true;}require(rejected);});
  test("wire_handshake_matches_fretwire",()=>{var frame=new PodFrame{Magic=0x28,Src=0x1001,Dst=0x03ef,Seq=0,Cmd=2,Arg=0x21000100,Body=new byte[]{0,0x10,0,0}};require(BitConverter.ToString(frame.Encode()).Replace("-","").ToLowerInvariant()=="0c0000280110ef03000000020001002100100000");});
  test("wire_ir_select_envelope",()=>require(BitConverter.ToString(PodMsg.Encode(PodMsg.Map(102,1001,100,12,101,PodMsg.Map(112,0)))).Replace("-","").ToLowerInvariant()=="8366cd03e9640c65817000"));
  test("wire_decode_concatenated_frames",()=>{var f=new PodFrame{Src=1,Dst=2,Seq=3,Cmd=4,Body=new byte[]{1,2,3}};var b=f.Encode();var frames=PodFrame.Decode(b.Concat(b).ToArray());require(frames.Count==2&&frames[1].Body.SequenceEqual(f.Body));});
  test("wire_detect_truncation",()=>{bool rejected=false;try{PodFrame.Decode(new byte[2]);}catch(InvalidDataException){rejected=true;}require(rejected);});
  test("wire_upload_credit_and_full_readback",()=>{var fake=new NamWireFixture();using(var wire=new PodWireSession(fake,s=>{})){wire.Handshake();var payload=NamCapture.AudioPayload(capture.Wave);var got=wire.UploadVerified(51,"NAM_test",payload);require(got.SequenceEqual(payload)&&fake.DataFrames>16&&fake.DataBytes==PodFrame.Tlv(2,PodWireSession.UploadBody(1001,51,"NAM_test",payload)).Length);}});
  test("wire_refuse_occupied_unnamed_ir",()=>{var fake=new NamWireFixture{Occupied=true};using(var wire=new PodWireSession(fake,s=>{})){wire.Handshake();bool rejected=false;try{wire.UploadVerified(51,"NAM_test",NamCapture.AudioPayload(capture.Wave));}catch(IOException){rejected=true;}require(rejected&&fake.DataFrames==0);}});
  test("wire_stop_on_missing_credit",()=>{var fake=new NamWireFixture{DropCreditAt=2};using(var wire=new PodWireSession(fake,s=>{})){wire.Handshake();bool rejected=false;try{wire.UploadVerified(51,"NAM_test",NamCapture.AudioPayload(capture.Wave));}catch(IOException){rejected=true;}require(rejected&&fake.DataBytes==1024&&fake.Stored==null);}});
  test("wire_last_credit_requires_readback_instead",()=>{var fake=new NamWireFixture{DropCreditAt=17};using(var wire=new PodWireSession(fake,s=>{})){wire.Handshake();var payload=NamCapture.AudioPayload(capture.Wave);require(wire.UploadVerified(51,"NAM_test",payload).SequenceEqual(payload));}});
  test("wire_read_stored_blob_transaction_from_real_trace",()=>{var fake=new NamWireFixture{StoredBlobTransaction=true};using(var wire=new PodWireSession(fake,s=>{})){wire.Handshake();var payload=NamCapture.AudioPayload(capture.Wave);require(wire.UploadVerified(51,"NAM_test",payload).SequenceEqual(payload));}});
  test("app_reopens_wire_for_every_operation",()=>{var device=new NamFixtureDevice();var peers=new List<NamWireFixture>();var app=new NamDataSession(Path.Combine(folder,"fresh-session-app-"+Guid.NewGuid().ToString("N")),s=>{},(p,log)=>{var fake=new NamWireFixture(device){OneTransferOnly=true};peers.Add(fake);return new PodWireSession(fake,log);});try{app.Connect().GetAwaiter().GetResult();app.Refresh().GetAwaiter().GetResult();string outcome=app.Send(capture).GetAwaiter().GetResult();require(outcome.Contains("verificado")&&peers.Count==6&&peers.All(p=>p.TransferSessions==1)&&device.Stored.SequenceEqual(NamCapture.AudioPayload(capture.Wave)));}finally{app.Disconnect().GetAwaiter().GetResult();}});
  test("app_honors_user_selected_destination",()=>{var device=new NamFixtureDevice();var app=new NamDataSession(Path.Combine(folder,"selected-slot-"+Guid.NewGuid().ToString("N")),s=>{},(p,log)=>new PodWireSession(new NamWireFixture(device){OneTransferOnly=true},log));try{app.Connect().GetAwaiter().GetResult();var expected=app.State.Bank[7];string result=app.Send(capture,7,false,expected).GetAwaiter().GetResult();require(device.Slot==7&&result.Contains("Model 8"));}finally{app.Disconnect().GetAwaiter().GetResult();}});
  test("app_refuses_destination_changed_since_selection",()=>{var device=new NamFixtureDevice();var peers=new List<NamWireFixture>();var app=new NamDataSession(Path.Combine(folder,"changed-slot-"+Guid.NewGuid().ToString("N")),s=>{},(p,log)=>{var peer=new NamWireFixture(device);peers.Add(peer);return new PodWireSession(peer,log);});try{app.Connect().GetAwaiter().GetResult();var expected=app.State.Bank[7];device.Slot=7;device.Stored=NamCapture.AudioPayload(capture.Wave);device.Name="My cabinet";bool rejected=false;try{app.Send(capture,7,true,expected).GetAwaiter().GetResult();}catch(IOException){rejected=true;}require(rejected&&peers.All(p=>p.DataFrames==0));}finally{app.Disconnect().GetAwaiter().GetResult();}});
  test("app_refuses_cabinet_even_with_replace_flag",()=>{var device=new NamFixtureDevice{Stored=NamCapture.AudioPayload(capture.Wave),Name="My cabinet"};var peers=new List<NamWireFixture>();var app=new NamDataSession(Path.Combine(folder,"cabinet-guard-"+Guid.NewGuid().ToString("N")),s=>{},(p,log)=>{var peer=new NamWireFixture(device);peers.Add(peer);return new PodWireSession(peer,log);});try{app.Connect().GetAwaiter().GetResult();var expected=app.State.Bank[51];bool rejected=false;try{app.Send(capture,51,true,expected).GetAwaiter().GetResult();}catch(IOException){rejected=true;}require(rejected&&peers.All(p=>p.DataFrames==0));}finally{app.Disconnect().GetAwaiter().GetResult();}});
  test("app_replace_nam_keeps_exact_backup",()=>{var old=NamCapture.AudioPayload(capture.Wave);var device=new NamFixtureDevice{Stored=old,Name="NAM_"+NamCapture.Sha(old).Substring(0,12)};string run=Path.Combine(folder,"replace-backup-"+Guid.NewGuid().ToString("N"));var app=new NamDataSession(run,s=>{},(p,log)=>new PodWireSession(new NamWireFixture(device){OneTransferOnly=true},log));try{app.Connect().GetAwaiter().GetResult();var next=NamCapture.Read(source,-5);var expected=app.State.Bank[51];app.Send(next,51,true,expected).GetAwaiter().GetResult();string backup=Directory.GetFiles(run,"previous.float32.bin",SearchOption.AllDirectories).Single();require(File.ReadAllBytes(backup).SequenceEqual(old)&&device.Slot==51&&device.Stored.SequenceEqual(NamCapture.AudioPayload(next.Wave)));}finally{app.Disconnect().GetAwaiter().GetResult();}});
  test("short_name_contract_fits_native31_byte_field",()=>{string hash=NamCapture.Sha(NamCapture.AudioPayload(capture.Wave));string name=NamTitle.DeviceName(hash,"ABCDEFGHIJKLMN");require(name.Length==31&&NamCatalog.ManagedName(name)&&NamTitle.Preview(53,"FRIEDMAN HBE")=="53. FRIEDMAN HBE"&&NamTitle.Preview(0,"")=="0. Dev by Conr4d");});
  test("legacy_and_named_nam_tags_keep_strict_hash_prefix",()=>{string hash=NamCapture.Sha(NamCapture.AudioPayload(capture.Wave));require(NamCatalog.ManagedName("NAM_"+hash.Substring(0,12))&&NamCatalog.ManagedName(NamTitle.DeviceName(hash,"FRIEDMAN HBE"))&&!NamCatalog.ManagedName("NAM_0123456789az TITLE")&&!NamCatalog.ManagedName("NAM_0123456789ab ")&&!NamCatalog.ManagedName("NAM_0123456789ab ../CAB")&&!NamTitle.Valid("NOMBRE EXCESIVAMENTE LARGO")&&!NamTitle.Valid("A/B"));});
  test("named_upload_keeps_audio_payload_exact",()=>{var device=new NamFixtureDevice();var app=new NamDataSession(Path.Combine(folder,"named-slot-"+Guid.NewGuid().ToString("N")),s=>{},(p,log)=>new PodWireSession(new NamWireFixture(device){OneTransferOnly=true},log));try{app.Connect().GetAwaiter().GetResult();app.Send(capture,52,false,app.State.Bank[52],"FRIEDMAN HBE").GetAwaiter().GetResult();require(device.Slot==52&&device.Name.EndsWith(" FRIEDMAN HBE")&&device.Stored.SequenceEqual(NamCapture.AudioPayload(capture.Wave))&&app.Catalog.Friendly(app.State.Bank[52])==capture.Name);}finally{app.Disconnect().GetAwaiter().GetResult();}});
  test("named_replacement_preserves_previous_hash_and_backup",()=>{var old=NamCapture.AudioPayload(capture.Wave);string hash=NamCapture.Sha(old);var device=new NamFixtureDevice{Stored=old,Name=NamTitle.DeviceName(hash,"FRIEDMAN HBE")};string run=Path.Combine(folder,"replace-named-"+Guid.NewGuid().ToString("N"));var app=new NamDataSession(run,s=>{},(p,log)=>new PodWireSession(new NamWireFixture(device){OneTransferOnly=true},log));try{app.Connect().GetAwaiter().GetResult();app.Send(NamCapture.Read(source,-5),51,true,app.State.Bank[51],"FRIEDMAN HBE").GetAwaiter().GetResult();require(File.ReadAllBytes(Directory.GetFiles(run,"previous.float32.bin",SearchOption.AllDirectories).Single()).SequenceEqual(old)&&device.Name.StartsWith("NAM_"));}finally{app.Disconnect().GetAwaiter().GetResult();}});
  test("forged_named_tag_never_authorizes_overwriting_ir",()=>{var device=new NamFixtureDevice{Stored=NamCapture.AudioPayload(capture.Wave),Name="NAM_000000000000 CABINET"};var peers=new List<NamWireFixture>();var app=new NamDataSession(Path.Combine(folder,"forged-tag-"+Guid.NewGuid().ToString("N")),s=>{},(p,log)=>{var peer=new NamWireFixture(device);peers.Add(peer);return new PodWireSession(peer,log);});try{app.Connect().GetAwaiter().GetResult();bool rejected=false;try{app.Send(NamCapture.Read(source,-5),51,true,app.State.Bank[51],"FRIEDMAN HBE").GetAwaiter().GetResult();}catch(IOException){rejected=true;}require(rejected&&peers.All(p=>p.DataFrames==0));}finally{app.Disconnect().GetAwaiter().GetResult();}});
  Action<string,Action<Dictionary<string,object>>> bad=(name,mutate)=>test(name,()=>{var root=NamCapture.Dict(json.DeserializeObject(File.ReadAllText(source)));var models=(object[])NamCapture.Dict(root["config"])["submodels"];var lite=NamCapture.Dict(NamCapture.Dict(models[0])["model"]);mutate(lite);string file=Path.Combine(folder,name+".nam");File.WriteAllText(file,json.Serialize(root));bool rejected=false;try{NamCapture.Read(file);}catch(Exception){rejected=true;}require(rejected);});
  bad("reject_wrong_sample_rate",m=>m["sample_rate"]=44100);
  bad("reject_wrong_weight_count",m=>m["weights"]=new object[]{0});
  bad("reject_unsupported_kernel",m=>{var lc=NamCapture.Dict(((object[])NamCapture.Dict(m["config"])["layers"])[0]);lc["kernel_sizes"]=new object[]{1};});
  bad("reject_active_film",m=>{var lc=NamCapture.Dict(((object[])NamCapture.Dict(m["config"])["layers"])[0]);NamCapture.Dict(lc["conv_pre_film"])["active"]=true;});
  bad("reject_gated_network",m=>{var lc=NamCapture.Dict(((object[])NamCapture.Dict(m["config"])["layers"])[0]);((object[])lc["gating_mode"])[0]="sigmoid";});
  File.WriteAllText(Path.Combine(folder,"results.json"),json.Serialize(new{status=failed==0?"PASS":"FAIL",checks=results.Count,failed=failed,USB_opened=false,firmware_written=false,results=results}));Console.WriteLine("NAM tests "+(results.Count-failed)+"/"+results.Count);return failed==0?0:1;
 }
}
